141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        normalizeAddress(ownerFieldsDto);
145	        rejectBlankOwnerFields(ownerFieldsDto);
146	        rejectInvalidPostcode(ownerFieldsDto);
147	        normalizeTelephone(ownerFieldsDto);
148	        normalizeEmail(ownerFieldsDto);
149	        String householdId = HouseholdNormalizer.toHouseholdId(
150	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
151	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
152	        rejectCityAtCapacity(ownerFieldsDto.getCity());
153	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
154	        long registeredThatDay = countRegisteredOn(registrationDate);
155	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
156	        HttpHeaders headers = new HttpHeaders();
157	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
158	        owner.setRegistrationDate(registrationDate);
159	        owner.setHouseholdId(householdId);
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
162	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
163	        this.clinicService.saveOwner(owner);
164	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
165	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        headers.setLocation(UriComponentsBuilder.newInstance()
168	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
169	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
170	    }
