269	    /**
270	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
271	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
272	     * the request body already rejects null and empty values, but permits whitespace-only strings
273	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
274	     * that gap so every required field must carry a non-blank value.
275	     *
276	     * @param ownerFieldsDto the submitted owner fields
277	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
278	     */
279	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
280	        List<String> missing = new ArrayList<>();
281	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
282	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
283	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
284	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
285	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
286	        if (!missing.isEmpty()) {
287	            throw new InvalidOwnerFieldsException(missing);
288	        }
289	    }
290	
291	    /**
292	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
293	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
294	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
295	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
296	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
297	     * {@link PostcodeValidator}.
298	     *
299	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
300	     *                       {@link #rejectBlankOwnerFields} having already run)
301	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
302	     */
303	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
304	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
305	            throw new InvalidOwnerFieldsException(List.of("postcode"));
306	        }
307	    }
308	
309	    private void addIfBlank(List<String> missing, String fieldName, String value) {
310	        if (value == null || value.isBlank()) {
311	            missing.add(fieldName);
312	        }
313	    }
314	
315	    /**
316	     * Normalizes the submitted {@code address} on create to its canonical form (see
317	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
318	     * stored and returned, and the form every later address comparison (the required-field check,
319	     * household duplicate detection and the shared household id) is judged on. A null address is left
320	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
321	     * after normalization likewise reduces to the empty string and is rejected there.
322	     *
323	     * @param ownerFieldsDto the submitted owner fields
324	     */
325	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
326	        String address = ownerFieldsDto.getAddress();
327	        if (address == null) {
328	            return;
329	        }
330	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
331	    }
332	
333	    /**
334	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
335	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
336	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
337	     * {@code 400 Bad Request}.
338	     *
339	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
340	     *                       {@link #rejectBlankOwnerFields} having already run)
341	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
342	     */
343	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
344	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
345	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
346	        ownerFieldsDto.setTelephone(normalized);
347	    }
348	
349	    /**
350	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
351	     * untouched (email is optional). When present it is reduced to its canonical form (see
352	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
353	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
354	     *
355	     * @param ownerFieldsDto the submitted owner fields
356	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
357	     */
358	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
359	        String email = ownerFieldsDto.getEmail();
360	        if (email == null || email.isBlank()) {
361	            return;
362	        }
363	        String normalized = EmailNormalizer.normalize(email)
364	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
365	        ownerFieldsDto.setEmail(normalized);
366	    }
367	
368	    /**
369	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
370	     * duplicate detection is now expressed through the single derived {@code identityKey}
371	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
372	     * which replaces the previously separate telephone, email and household checks. Two owners denote
373	     * the same person when their identities collide on the telephone - the identity's distinguishing
374	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
375	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
376	     * same household with different telephones have different identities and are both allowed; an email
377	     * or a household on its own no longer makes a duplicate.
378	     *
379	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
380	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
381	     * @param householdId    the household id derived for the owner being created (see
382	     *                       {@link HouseholdNormalizer#toHouseholdId})
383	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
384	     */
385	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
386	        String identityKey = OwnerIdentity.identityKey(
387	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
388	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
389	        boolean inUse = this.clinicService.findAllOwners().stream()
390	            .map(Owner::getTelephone)
391	            .filter(Objects::nonNull)
392	            .map(TelephoneNormalizer::toComparisonKey)
393	            .anyMatch(telephoneKey::equals);
394	        if (inUse) {
395	            throw new DuplicateOwnerIdentityException(identityKey);
396	        }
397	    }
