436	    /**
437	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
438	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
439	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
440	     *
441	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
442	     *             run)
443	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
444	     */
445	    private void rejectCityAtCapacity(String city) {
446	        long ownersInCity = this.clinicService.findAllOwners().stream()
447	            .map(Owner::getCity)
448	            .filter(Objects::nonNull)
449	            .filter(city::equalsIgnoreCase)
450	            .count();
451	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
452	            throw new OwnerCityAtCapacityException(city);
453	        }
454	    }
455	
456	    /**
457	     * Resolves the effective registration date for a create, rolled onto a business day. The
458	     * supplied date is used when present, otherwise the server's current date; either way the result
459	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
460	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
461	     * stored {@code registrationDate}, the membership number's year segment and the daily
462	     * create-limit's per-day count - is judged on this adjusted date.
463	     *
464	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
465	     *                                 default to the server's current date
466	     * @return the effective registration date, guaranteed to fall on a business day
467	     */
468	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
469	        LocalDate registrationDate =
470	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
471	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
472	    }
473	
474	    /**
475	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
476	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
477	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
478	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
479	     * Too Many Requests}.
480	     *
481	     * @param registrationDate   the create's effective registration date, already rolled onto a
482	     *                           business day by {@link #effectiveRegistrationDate}
483	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
484	     *                           {@code registrationDate} equals {@code registrationDate}
485	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
486	     *                                              owner registrations
487	     */
488	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
489	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
490	            throw new OwnerDailyRegistrationLimitException(registrationDate);
491	        }
492	    }
493	
494	    /**
495	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
496	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
497	     * bulk-signup warning are judged on.
498	     *
499	     * @param registrationDate the create's effective registration date, already rolled onto a business
500	     *                         day by {@link #effectiveRegistrationDate}
501	     * @return the number of existing owners registered on that day
502	     */
503	    private long countRegisteredOn(LocalDate registrationDate) {
504	        return this.clinicService.findAllOwners().stream()
505	            .map(Owner::getRegistrationDate)
506	            .filter(registrationDate::equals)
507	            .count();
508	    }
509	}
