242	    /**
243	     * Build a customer code formatted '<CITY3>-<LAST3>-<NNNN>', where CITY3 is the upper-cased
244	     * first three letters of the city, LAST3 the upper-cased first three letters of the last name
245	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of owners
246	     * already in that city (e.g. 'SYD-SMI-0007').
247	     */
248	    private String generateCustomerCode(String city, String lastName) {
249	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
250	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
251	        long sequence = ownerRepository.findAll().stream()
252	            .filter(o -> o.getCity() != null && o.getCity().equalsIgnoreCase(city))
253	            .count() + 1L;
254	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
255	    }
