275	    private <T> T findEntityById(Supplier<T> supplier) {
276	        try {
277	            return supplier.get();
278	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
279	            // Just ignore not found exceptions for Jdbc/Jpa realization
280	            return null;
281	        }
282	    }
