18	
19	import java.util.Map;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Validation of an owner's optional 4-digit postcode against the region derived from its city. Kept
24	 * separate from the owner controller and the {@code Owner} model so the rule lives in one place, as a
25	 * pure function with no web or persistence dependencies. Mirrors {@link LocalityResolver}, whose
26	 * city-to-region derivation this reuses.
27	 *
28	 * <p>A postcode must consist of exactly four digits, and when the city maps to a known region (see
29	 * {@link LocalityResolver}) the numeric value must fall within that region's fixed inclusive range
30	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region
31	 * (locality {@code UNKNOWN}) accepts any 4-digit postcode. A {@code null} postcode is not present and
32	 * is therefore always accepted; the presence check is the caller's responsibility.
33	 */
34	public abstract class PostcodeValidator {
35	
36	    /** A postcode is exactly four digits. */
37	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
38	
39	    /** Region -> inclusive 4-digit postcode range {low, high}. */
40	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
41	        "NSW", new int[] {2000, 2099},
42	        "VIC", new int[] {3000, 3099},
43	        "QLD", new int[] {4000, 4099});
44	
45	    /**
46	     * Whether the given postcode is valid for the given city. An absent ({@code null}) postcode is
47	     * valid; a present one must be four digits and, when the city has a known region, must fall within
48	     * that region's inclusive range. Any city with no known region accepts any 4-digit postcode.
49	     *
50	     * @param city     the owner's city (may be null)
51	     * @param postcode the owner's postcode (may be null when absent)
52	     * @return {@code true} when the postcode is absent or valid for the city, {@code false} otherwise
53	     */
54	    public static boolean isValid(String city, String postcode) {
55	        if (postcode == null) {
56	            return true;
57	        }
58	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
59	            return false;
60	        }
61	        int[] range = REGION_POSTCODES.get(LocalityResolver.resolve(city));
62	        if (range == null) {
63	            return true;
64	        }
65	        int value = Integer.parseInt(postcode);
66	        return value >= range[0] && value <= range[1];
67	    }
68	
69	}
