23	/**
24	 * Normalization and comparison of owner telephone numbers. Kept separate from the owner controller
25	 * and the {@code Owner} model so the rules for shaping and comparing a telephone live in one place,
26	 * as pure functions with no web or persistence dependencies.
27	 *
28	 * <p>A submitted telephone is reduced to its canonical <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
29	 * form, which is the value stored and returned. Spaces, dashes and brackets are stripped; a leading
30	 * {@code '+'} and its country code are kept when present, otherwise the country code {@code '+61'} is
31	 * assumed and a single leading {@code '0'} is dropped from the national digits. The result is accepted
32	 * only when 8 to 15 digits follow the {@code '+'} and, for a recognised country code, exactly as many
33	 * national digits follow the code as that country requires ({@code +61} requires 9, {@code +1} requires
34	 * 10). Two telephones denote the same number when their
35	 * {@linkplain #toComparisonKey(String) comparison keys} — their E.164 forms — are equal.
36	 */
37	public abstract class TelephoneNormalizer {
38	
39	    /** Characters stripped from a submitted telephone: spaces, dashes and brackets. */
40	    private static final String SEPARATORS = "[\\s()\\[\\]-]";
41	
42	    private static final int MIN_E164_DIGITS = 8;
43	
44	    private static final int MAX_E164_DIGITS = 15;
45	
46	    /**
47	     * The exact number of national (subscriber) digits required after each known country code.
48	     * A telephone whose country code appears here is accepted only when precisely this many
49	     * digits follow the code (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10).
50	     * Ordered longest-prefix-first so the country code is matched greedily.
51	     */
52	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = new LinkedHashMap<>();
53	
54	    static {
55	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("61", 9);
56	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("1", 10);
57	    }
58	
59	    /**
60	     * Reduce a submitted telephone to its canonical E.164 form, which is the value to be stored and
61	     * returned. Spaces, dashes and brackets are removed; when the number carries a leading {@code '+'}
62	     * its country code is kept, otherwise country code {@code 61} is assumed and a single leading
63	     * {@code '0'} is dropped from the national digits. The result is accepted only when 8 to 15 digits
64	     * follow the {@code '+'}.
65	     *
66	     * @param rawTelephone the submitted telephone (non-null)
67	     * @return the canonical E.164 telephone (e.g. {@code +61412345678}), or {@link Optional#empty()}
68	     *         if {@code rawTelephone} cannot form a valid E.164 number
69	     */
70	    public static Optional<String> normalize(String rawTelephone) {
71	        String cleaned = rawTelephone.replaceAll(SEPARATORS, "");
72	        String digits;
73	        if (cleaned.startsWith("+")) {
74	            digits = cleaned.substring(1);
75	        }
76	        else {
77	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
78	            digits = "61" + national;
79	        }
80	        if (!digits.matches("\\d+") || digits.length() < MIN_E164_DIGITS || digits.length() > MAX_E164_DIGITS) {
81	            return Optional.empty();
82	        }
83	        if (!hasValidNationalLength(digits)) {
84	            return Optional.empty();
85	        }
86	        return Optional.of("+" + digits);
87	    }
88	
89	    /**
90	     * Checks the national (subscriber) portion of an all-digit E.164 number against the length its
91	     * country code requires. When the leading country code is one we recognise (see
92	     * {@link #NATIONAL_LENGTH_BY_COUNTRY_CODE}), the remaining digits must number exactly the value
93	     * mapped for that code; an unrecognised country code is left to the generic 8-to-15-digit bound.
94	     *
95	     * @param digits the E.164 number without its leading {@code '+'} (digits only)
96	     * @return {@code true} if the national-number length is valid for the country code
97	     */
98	    private static boolean hasValidNationalLength(String digits) {
99	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
100	            String countryCode = entry.getKey();
101	            if (digits.startsWith(countryCode)) {
102	                int nationalLength = digits.length() - countryCode.length();
103	                return nationalLength == entry.getValue();
104	            }
105	        }
106	        return true;
107	    }
108	
109	    /**
110	     * The key used to decide whether two telephones denote the same number: the telephone's canonical
111	     * E.164 form, so telephones stored in different textual shapes still compare equal. A value that
112	     * does not form a valid E.164 number (e.g. legacy data) falls back to its separator-stripped form.
113	     *
114	     * @param telephone a stored or already-normalized telephone (non-null)
115	     * @return the comparison key
116	     */
117	    public static String toComparisonKey(String telephone) {
118	        return normalize(telephone).orElseGet(() -> telephone.replaceAll(SEPARATORS, ""));
119	    }
120	
121	}
