19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	
22	/**
23	 * Adjustment of a date onto a business day. Kept separate from the owner controller and the
24	 * {@code Owner} model so the rule lives in one place, as a pure function with no web or persistence
25	 * dependencies. Mirrors {@link LocalityResolver}, which does the same for localities.
26	 *
27	 * <p>A business day is any weekday (Monday through Friday). A date that already falls on a weekday is
28	 * returned unchanged; a Saturday or Sunday is rolled forward to the following Monday.
29	 */
30	public abstract class BusinessDayAdjuster {
31	
32	    /**
33	     * Roll a date forward onto the next business day, leaving weekdays unchanged.
34	     *
35	     * @param date the date to adjust (must not be null)
36	     * @return the same date when it is a weekday, otherwise the following Monday
37	     */
38	    public static LocalDate toBusinessDay(LocalDate date) {
39	        DayOfWeek dayOfWeek = date.getDayOfWeek();
40	        if (dayOfWeek == DayOfWeek.SATURDAY) {
41	            return date.plusDays(2);
42	        }
43	        if (dayOfWeek == DayOfWeek.SUNDAY) {
44	            return date.plusDays(1);
45	        }
46	        return date;
47	    }
48	
49	}
